from fastapi import FastAPI, Security
from fastapi.security import SecurityScopes
from fastapi.testclient import TestClient

app = FastAPI()

def leaf(scopes: SecurityScopes):
    return scopes.scopes

def mid(l=Security(leaf, scopes=["mid"])):
    return l

@app.get("/one")
def one(m=Security(mid, scopes=["root"])):
    return m

# sibling mutation case
def leaf_a(scopes: SecurityScopes):
    return scopes.scopes

def leaf_b(scopes: SecurityScopes):
    return scopes.scopes

def parent(a=Security(leaf_a, scopes=["a"]), b=Security(leaf_b, scopes=["b"])):
    return {"a": a, "b": b}

@app.get("/two")
def two(p=Security(parent, scopes=["root"])):
    return p

client = TestClient(app)
print("one:", client.get("/one").json())
print("two:", client.get("/two").json())
EOF
